# owner: platform
from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans


def _clock(minute: int) -> str:
    hours, mins = divmod(minute, 60)
    return f"{hours:02d}:{mins:02d}"


def _outside(span: Span, opening: Span) -> bool:
    return (span.start < opening.start
            or span.end > opening.end)


def _validate(spans: List[Span], opening: Span) -> None:
    for span in spans:
        if _outside(span, opening):
            raise ValueError(
                f"outside opening hours: {span}"
            )


def _holes(merged: List[Span], opening: Span) -> List[Span]:
    begins = [opening.start] + [item.end for item in merged]
    stops = [item.start for item in merged] + [opening.end]
    return [Span(low, high) for low, high in zip(begins, stops)
            if low < high]


# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    merged = merge_spans(worked)
    _validate(merged, opening)
    return [
        f"gap {_clock(hole.start)}-{_clock(hole.end)}"
        f" ({hole.minutes} min)"
        for hole in _holes(merged, opening)
    ]
EOF
cat > tests/test_gaps.py <<'EOF'
# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(540, 1020)


class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_edges_and_overlap(self):
        worked = [Span(600, 700), Span(650, 900)]
        self.assertEqual(find_gaps(worked, OPEN), [
            "gap 09:00-10:00 (60 min)",
            "gap 15:00-17:00 (120 min)"
        ])

    def test_full_cover(self):
        self.assertEqual(find_gaps([OPEN], OPEN), [])

    def test_outside_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 600)], OPEN)
EOF
